const { chromium } = require("/home/arnab-smnta/.nvm/versions/node/v24.10.0/lib/node_modules/@playwright/cli/node_modules/playwright");
const path = require("path");

const BASE = "http://localhost:3100";
const OUT = path.join(__dirname, "shots");
const channel = process.env.CHANNEL || undefined; // "chrome" for H.264

function collect(page, label, logs) {
  page.on("console", (m) => {
    const t = m.type();
    if (["error", "warning", "warn"].includes(t) || m.text().includes("[landing]"))
      logs.push(`[${label}] ${t}: ${m.text().slice(0, 300)}`);
  });
  page.on("pageerror", (e) => logs.push(`[${label}] pageerror: ${e.message}`));
}

async function state(page) {
  return page.evaluate(() => {
    const secs = [...document.querySelectorAll("[data-landing] section")];
    const nav = document.querySelector('nav[aria-label="Main"]');
    const canvas = document.querySelector("[data-landing] canvas");
    const video = document.querySelector("[data-landing] video");
    return {
      scrollY: Math.round(window.scrollY),
      opac: secs.map((s) => Number(getComputedStyle(s).opacity).toFixed(2)),
      inert: secs.map((s) => s.inert),
      navColor: nav && getComputedStyle(nav).color,
      canvasOpacity: canvas && getComputedStyle(canvas).opacity,
      videoTime: video && Number(video.currentTime.toFixed(2)),
      counts: window.__landingScrub,
      h1Font: getComputedStyle(document.querySelector("h1")).fontFamily,
    };
  });
}

async function scrollToP(page, p) {
  await page.evaluate((p) => {
    const span = document.querySelector("[data-landing] > div").offsetHeight - innerHeight;
    window.scrollTo({ top: p * span, behavior: "instant" });
  }, p);
  await page.waitForTimeout(2500);
}

(async () => {
  const browser = await chromium.launch({ channel });
  const logs = [];
  const report = {};

  for (const [name, vp] of [["desktop", { width: 1440, height: 900 }], ["mobile", { width: 390, height: 844 }]]) {
    const ctx = await browser.newContext({ viewport: vp });
    const page = await ctx.newPage();
    collect(page, name, logs);
    await page.goto(BASE + "/", { waitUntil: "load" });
    const live = await page
      .waitForFunction(() => getComputedStyle(document.querySelector("[data-landing] canvas")).opacity === "1", null, { timeout: 45000 })
      .then(() => true, () => false);
    report[name] = { canvasLive: live };
    for (const p of [0, 0.45, 0.85]) {
      await scrollToP(page, p);
      report[name][p] = await state(page);
      await page.screenshot({ path: `${OUT}/${channel || "chromium"}-${name}-p${p}.png` });
    }
    if (name === "mobile") {
      await scrollToP(page, 0);
      await page.click('button[aria-label="Open menu"]');
      await page.waitForTimeout(900);
      report.menu = await page.evaluate(() => ({
        bodyOverflow: document.body.style.overflow,
        focused: document.activeElement?.getAttribute("aria-label"),
        footer: [...document.querySelectorAll("#landing-mobile-menu > div > div:last-child a")].map((a) => a.getAttribute("href")),
      }));
      await page.screenshot({ path: `${OUT}/${channel || "chromium"}-mobile-menu.png` });
      await page.keyboard.press("Escape");
      await page.waitForTimeout(700);
      report.menuAfterEsc = await page.evaluate(() => ({
        bodyOverflow: document.body.style.overflow,
        focused: document.activeElement?.getAttribute("aria-label"),
      }));
    }
    if (name === "desktop") {
      report.links = await page.evaluate(() => ({
        nav: [...document.querySelectorAll('nav[aria-label="Main"] > ul a')].map((a) => `${a.textContent}->${a.getAttribute("href")}`),
        right: [...document.querySelectorAll('nav[aria-label="Main"] > div a')].map((a) => `${a.textContent}->${a.getAttribute("href")}`),
        s1: document.querySelector('a[aria-label="Go to today\'s news"]')?.getAttribute("href"),
        cta: [...document.querySelectorAll("[data-landing] section a")].map((a) => a.getAttribute("href")),
        h1s: document.querySelectorAll("h1").length,
        header: !!document.querySelector("header"),
        footer: !!document.querySelector("footer"),
